func readRecallCorpus(t *testing.T) []recallIssue {
	t.Helper()
	f, err := os.Open("testdata/recall/corpus.json.gz")
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	zr, err := gzip.NewReader(f)
	if err != nil {
		t.Fatal(err)
	}
