// of the kept issue when the analysis used one.
func recallBacklog(t *testing.T, corpus []recallIssue, closed, kept int) []fakeIssue {
	t.Helper()
	before, err := os.ReadFile(fmt.Sprintf("testdata/recall/premerge/%d.body.before-%d.md", kept, closed))
